const formatValue = (num: number) => {
  if (num >= 1000000) return (num / 1000000).toFixed(1) + "M";
  if (num >= 1000) return (num / 1000).toFixed(1) + "K";
  return Math.floor(num).toString();
};

const SocialMetricsDrop: React.FC<SocialMetricsDropProps> = ({
  backgroundColor = "#09090B",
  transparentBackground = false,
  durationInSeconds = 2,
  accentColor = "#FF3B30", // Red for dropping metric
  neutralColor = "#34C759", // Green for initial state
  trackColor = "#1C1C1E",
  textColor = "#FFFFFF",
  likesStartValue = 24500,
  commentsStartValue = 1840,
  sharesStartValue = 4200,
  viewsStartValue = 158000,
  dropPercentage = 0.75, // Metrics drop by 75%
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = Math.max(1, durationInSeconds * fps);
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const metricsData = React.useMemo(
    () => [
      { id: "views", label: "Views", start: viewsStartValue, icon: Icons.views },
      { id: "likes", label: "Likes", start: likesStartValue, icon: Icons.likes },
      { id: "comments", label: "Comments", start: commentsStartValue, icon: Icons.comments },
      { id: "shares", label: "Shares", start: sharesStartValue, icon: Icons.shares },
    ],
    [viewsStartValue, likesStartValue, commentsStartValue, sharesStartValue]
  );

  // Layout calculations optimized for 9:16 vertical stack
  const containerWidth = width * 0.85;
  const itemGap = height * 0.04;
  const iconSize = width * 0.08;
  const fontSize = width * 0.07;
  const barHeight = height * 0.015;

  // Global Timing logic
  const introFrames = 15;
  const exitFrames = 15;
  const activeDuration = Math.max(0, totalFrames - introFrames - exitFrames);
  
  // Begin dropping 20% into the active hold time to ensure fast pacing
  const dropStartBase = introFrames + Math.max(2, activeDuration * 0.2);
  const exitStartBase = totalFrames - exitFrames;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          width: containerWidth,
          height: "100%",
          margin: "0 auto",
          justifyContent: "center",
          gap: itemGap,
          transition: "none",
        }}
      >
        {metricsData.map((metric, i) => {
          // Staggering logic for each metric row
          const stagger = i * 2;
          const introSpring = spring({
            frame: frame - stagger,
            fps,
            config: { damping: 14, stiffness: 120 },
          });

          // Sharp, clear downward drop physics
          const dropSpring = spring({
            frame: frame - (dropStartBase + stagger),
            fps,
            config: { damping: 12, stiffness: 160 }, // Stiff for quick drop
          });

          const exitSpring = spring({
            frame: frame - (exitStartBase + stagger * 0.5),
            fps,
            config: { damping: 16, stiffness: 140 },
          });

          // Calculations
          const targetValue = metric.start * (1 - dropPercentage);
          const currentValue = interpolate(dropSpring, [0, 1], [metric.start, targetValue]);
          const barScaleX = interpolate(dropSpring, [0, 1], [1, 1 - dropPercentage]);

          // Visual transitions indicating engagement dropping
          const currentColor = interpolateColors(
            dropSpring,
            [0, 0.2], // Rapid color shift
            [neutralColor, accentColor]
          );

          // Downward trend arrow animation
          const trendIconOpacity = interpolate(dropSpring, [0, 0.2, 1], [0, 1, 1], {
            extrapolateRight: "clamp",
          });
          const trendIconY = interpolate(dropSpring, [0, 1], [-15, 0]);
          const trendIconScale = interpolate(dropSpring, [0, 0.4], [0.5, 1], {
            extrapolateRight: "clamp",
          });

          // Intro & Outro spatial animations
          const yOffset =
            interpolate(introSpring, [0, 1], [60, 0]) +
            interpolate(exitSpring, [0, 1], [0, 60]);

          const opacity =
            interpolate(introSpring, [0, 0.5], [0, 1], { extrapolateRight: "clamp" }) *
            interpolate(exitSpring, [0, 0.5], [1, 0], { extrapolateRight: "clamp" });

          return (
            <div
              key={metric.id}
              style={{
                opacity,
                transform: `translateY(${yOffset}px)`,
                transition: "none",
                display: "flex",
                flexDirection: "column",
                gap: height * 0.015,
              }}
            >
              {/* Header: Label & Metric Value */}
              <div
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  color: textColor,
                  transition: "none",
                }}
              >
                <div style={{ display: "flex", alignItems: "center", gap: width * 0.03 }}>
                  <div style={{ width: iconSize, height: iconSize, opacity: 0.8 }}>
                    {metric.icon}
                  </div>
                  <span style={{ fontSize, fontWeight: 600 }}>{metric.label}</span>
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: width * 0.02 }}>
                  <div
                    style={{
                      width: iconSize * 0.8,
                      height: iconSize * 0.8,
                      color: accentColor,
                      opacity: trendIconOpacity,
                      transform: `translateY(${trendIconY}px) scale(${trendIconScale})`,
                      transition: "none",
                    }}
                  >
                    {Icons.trendDown}
                  </div>
                  <span
                    style={{
                      fontSize,
                      fontWeight: 800,
                      color: currentColor,
                      fontVariantNumeric: "tabular-nums",
                      minWidth: width * 0.2, // Prevents layout jump when numbers change
                      textAlign: "right",
                    }}
                  >
                    {formatValue(currentValue)}
                  </span>
                </div>
              </div>

              {/* Data Bar */}
              <div
                style={{
                  width: "100%",
                  height: barHeight,
                  backgroundColor: trackColor,
                  borderRadius: barHeight / 2,
                  overflow: "hidden",
                  transition: "none",
                }}
              >
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    backgroundColor: currentColor,
                    borderRadius: barHeight / 2,
                    transform: `scaleX(${barScaleX})`,
                    transformOrigin: "left center",
                    transition: "none",
                  }}
                />
              </div>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default SocialMetricsDrop;